# TRIDENT Cleanup Script — review before running
# Generated: {TIMESTAMP}
# Target process: {PROCESS_NAME} (PID {PID})
# Reason: Threat score {THREAT_SCORE}/10 · Trust: {TRUST_LEVEL} · Confidence: {CONFIDENCE}
#
# This script was generated by TRIDENT based on a decision you confirmed.
# Read every line before running. Every action is listed. Nothing happens
# silently.
#
# Run with:  powershell -ExecutionPolicy Bypass -File .\<this-file>.ps1

$ErrorActionPreference = "Stop"

Write-Host "[TRIDENT] Stopping process tree..." -ForegroundColor Cyan

# ─── 1. Stop the process tree (leaf-first) ───
$rootPid = {PID}
$childPids = {CHILD_PIDS}

foreach ($pid in $childPids) {
    Write-Host "[TRIDENT] Stopping child PID $pid"
    Stop-Process -Id $pid -Force -ErrorAction SilentlyContinue
}

Write-Host "[TRIDENT] Stopping root PID $rootPid"
Stop-Process -Id $rootPid -Force -ErrorAction SilentlyContinue

Start-Sleep -Milliseconds 500

# Verify
$stillAlive = Get-Process -Id $rootPid -ErrorAction SilentlyContinue
if ($stillAlive) {
    Write-Host "[TRIDENT] ERROR: Process $rootPid is still alive. Aborting." -ForegroundColor Red
    exit 1
}

Write-Host "[TRIDENT] Process tree stopped." -ForegroundColor Green

# ─── 2. Remove matching Windows services ───
Write-Host "[TRIDENT] Checking for matching services..." -ForegroundColor Cyan

$services = {SERVICE_NAMES}
foreach ($svc in $services) {
    Write-Host "[TRIDENT] Stopping and deleting service: $svc"
    Stop-Service -Name $svc -Force -ErrorAction SilentlyContinue
    sc.exe delete $svc
}

# ─── 3. Remove autostart entries ───
Write-Host "[TRIDENT] Checking autostart entries..." -ForegroundColor Cyan

# Registry Run keys
$runKeys = @(
    "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run",
    "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run",
    "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce",
    "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce"
)

$runEntries = {RUN_ENTRY_NAMES}
foreach ($key in $runKeys) {
    foreach ($entry in $runEntries) {
        if (Get-ItemProperty -Path $key -Name $entry -ErrorAction SilentlyContinue) {
            Write-Host "[TRIDENT] Removing $key\$entry"
            Remove-ItemProperty -Path $key -Name $entry -Force
        }
    }
}

# Scheduled tasks
$tasks = {SCHEDULED_TASKS}
foreach ($task in $tasks) {
    Write-Host "[TRIDENT] Deleting scheduled task: $task"
    schtasks /Delete /TN $task /F
}

# Startup folder shortcuts
$startupShortcuts = {STARTUP_SHORTCUTS}
foreach ($shortcut in $startupShortcuts) {
    Write-Host "[TRIDENT] Deleting startup shortcut: $shortcut"
    Remove-Item -Path $shortcut -Force -ErrorAction SilentlyContinue
}

# ─── 4. Remove files (whitelist-guarded) ───
Write-Host "[TRIDENT] Checking files..." -ForegroundColor Cyan

$filesToRemove = {FILES_TO_REMOVE}
$allowedPaths = @(
    "$env:APPDATA",
    "$env:LOCALAPPDATA",
    "$env:TEMP",
    "$env:USERPROFILE\Downloads",
    "C:\ProgramData"
)

foreach ($file in $filesToRemove) {
    $resolved = Resolve-Path -Path $file -ErrorAction SilentlyContinue
    if (-not $resolved) { continue }

    $isAllowed = $false
    foreach ($allowed in $allowedPaths) {
        if ($resolved.Path.StartsWith($allowed, [StringComparison]::OrdinalIgnoreCase)) {
            $isAllowed = $true
            break
        }
    }

    if ($isAllowed) {
        Write-Host "[TRIDENT] Deleting $($resolved.Path)"
        Remove-Item -Path $resolved.Path -Recurse -Force -ErrorAction SilentlyContinue
    } else {
        Write-Host "[TRIDENT] SKIPPED (outside whitelist): $($resolved.Path)" -ForegroundColor Yellow
    }
}

Write-Host ""
Write-Host "[TRIDENT] Cleanup complete." -ForegroundColor Green
Write-Host "[TRIDENT] Review the log at {LOG_PATH} for the full audit trail."
